<script lang="ts" setup>
  import { ref } from 'vue';
  import { useRouter } from 'vue-router';
  // @ts-ignore
  import InfoFromModal from './InfoFromModal.vue';
  // @ts-ignore
  import { SettingOutlined, ContainerOutlined } from '@vicons/antd';

  const router = useRouter();
  const showModal = ref(false);
  const actionType = ref('');
  const actionTitle = ref('');

  const handleEdit = (type: string) => {
    if (type === 'wechat') {
      actionTitle.value = '微信接入设置';
    } else if (type === 'sms') {
      actionTitle.value = '短信接入设置';
    } else if (type === 'mail') {
      actionTitle.value = '邮件接入设置';
    }
    actionType.value = type;
    showModal.value = true;
  };

  const handleTemplate = (type: string) => {
    router.push({ path: '/base/msg_templates', query: { group: type } });
  };
</script>

